import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"明夷","description":"周易集解 - 明夷","frontmatter":{"title":"明夷","description":"周易集解 - 明夷"},"headers":[],"relativePath":"classics/jijie/036.md","filePath":"classics/jijie/036.md"}'),l={name:"classics/jijie/036.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="明夷" tabindex="-1">明夷 <a class="header-anchor" href="#明夷" aria-label="Permalink to “明夷”">​</a></h1><h2 id="明夷-1" tabindex="-1">明夷 <a class="header-anchor" href="#明夷-1" aria-label="Permalink to “明夷”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>明夷，利艱貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：進必有所傷，故受之以明夷。夷者，傷也。</p><p>《九家易》曰：日在坤下，其明傷也。言進極當降，復入於地，故曰明夷也。</p><p>虞翻曰：夷，傷也。臨二之三而反晉也。明入地中，故傷矣。</p><p>虞翻曰：謂五也。五失位，變出成坎，為艱，故利艱貞矣。</p><p>鄭玄曰：夷，傷也。日出地上，其明乃光。至其入地，明則傷矣，故謂之明夷。日之明傷，猶聖人君子有明德，而遭亂世。抑在下位，則宜自艱，無幹事政，以避小人之害也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：明入地中，明夷。內文明而外柔順，以蒙大難，文王以之。利艱貞，晦其明也。內難而能正其志，箕子以之。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>蜀才曰：此本臨卦也。</p><p>案：夷，滅也。九二升三，六三降二，明入地中也。明入地中，則明滅也。</p><p>荀爽曰：明在地下，為坤所蔽，大難之象。大難，文王君臣相事，故言大難也。</p><p>虞翻曰：以，用也。三喻文王。大難謂坤。坤為弒父，迷亂荒淫，若紂殺比干。三幽坎中，象文王之拘羑里。震為諸侯，喻從文王者，紂懼出之，故｢以蒙大難｣，得身全矣。</p><p>虞翻曰：箕子，紂諸父。故稱內難。五乾天位，今化為坤，箕子之象。坤為晦，箕子正之。出五成坎，體離，重明麗正。坎為志，故｢正其志，箕子以之｣，而紂奴之矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：明入地中，明夷。君子以蒞眾，用晦而明。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：而，如也。君子謂三。體師象。以坎蒞坤。坤為眾，為晦，離為明，故用晦如明也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，明夷於飛，垂其翼。君子於行，三日不食。有攸往，主人有言。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>荀爽曰：火性炎上，離為飛鳥，故曰於飛。為坎所抑，故曰垂其翼。陽為君子。三者，陽德成也。日以喻君。不食者，不得君祿食也。陽未居五，陰暗在上。初有明德，恥食其祿，故曰｢君子於行，三日不食｣也。</p><p>《九家易》曰：四者初應，眾陰在上，為主人也。初欲上居五，則眾陰有言。言，謂震也。四五體震，為雷聲，故曰｢有攸往，主人有言｣也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：君子於行，義不食也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：闇昧在上，有明德者，義不食祿也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，明夷於左股，用拯馬壯，吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>《九家易》曰：左股謂初，為二所夷也。離為飛鳥，蓋取小過之義，鳥飛舒翼而行。夷者，傷也。今初傷，垂翼在下故曰｢明夷於左股｣矣。九三體坎，坎為馬也。二應與五，三與五同功，二以中和應天，應天合眾，欲升上三，以壯於五，故曰｢用拯馬壯，吉｣。</p><p>案：初為足。二居足上，股也。二互體坎。坎主左方，左股之象也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六二之吉，順以則也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：二欲上三居五，為天子。坎為法律。君有法，則眾陰當順從之矣。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，明夷於南狩，得其大首，不可疾貞。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>《九家易》曰：歲終田獵，名曰狩也。南者，九五大陽之位，故稱南也，闇昧道終，三可升上，而獵於五，得據大陽首位，故曰｢明夷於南狩，得其大首｣。自暗復明，當以漸次，不可卒正，故曰｢不可疾貞｣也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：南狩之志，乃大得也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>案：冬獵曰狩也。三互離坎，離南坎北，北主於冬，故曰南狩。五居暗主，三處明終，履正順時，拯難興衰者也。以臣伐君，故假言狩。既獲五上之大首，而三志乃大得也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，入於左腹，獲明夷之心，於出門庭。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>荀爽曰：陽稱左，謂九三也。腹者，謂五居坤，坤為腹也。四得位比三，處於順首。欲三上居五，以陽為腹心也。故曰｢入於左腹，獲明夷之心｣。言三明當出門庭，升五君位。</p><p>乾寶曰：一為室，二為戶，三為庭，四為門，故曰於出門庭矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：入於左腹，獲心意也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：四欲上三居五為坎，坎為心；四以坤爻為腹。故曰｢入於左腹，獲心意也｣。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，箕子之明夷，利貞。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>馬融曰：箕子，紂之諸父，明於天道、《洪範》之九疇。德可以王，故以當五，知紂之惡，無可奈何。同姓恩深，不忍棄去，被髮佯狂，以明為暗。故曰箕子之明夷。卒以全身，為武王師，名傳無窮，故曰利貞矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：箕子之貞，明不可息也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：體柔履中，內明外暗，群陰共掩，以夷其明。然以正為明，而不可息；以爻取象，箕子當之，故曰｢箕子之貞，明不可息也。｣</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，不明晦，初登於天，後入於地。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：應在三。離滅坤下，故不明晦。晉時在上麗乾，故登於天照四國。今反在下，故後入於地，失其則。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：初登於天，照四國也。後入於地，失則也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：最遠於陽，故曰不明晦也。初登於天，謂明出地上。下照於坤，坤為眾國，故曰照於四國也。喻陽之初興也。後入於地，謂明入地中，晝變為夜，暗晦之甚，故曰失則也。況紂之亂世也。此之二象，言晉與明夷，往複不已。故見暗則伐取之，亂則治取之，聖人因象設誡也。</p>',73)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
